-- Unit 1: publish the teacher-reviewed distractors inside each word's own data (vocabulary_items.senses).
-- Adds three fields to each word's sense: situationDistractors, gapDistractors (keyed by context id) and spellingErrors.
-- It merges those fields into the existing sense (everything already published is kept as it is). No wording, answers, contexts,
-- activities or schema change. Idempotent: safe to run more than once.
-- Run in the Supabase SQL editor, then run the verification queries at the bottom and report the numbers.
begin;
update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["Our coach set a strict timetable for every hour of the training camp.","Students must finish their homework before they are allowed to use the gym.","The athletes spent the whole afternoon in a compulsory team meeting.","Her part-time job at the sports shop takes up most of her weekends."],"gapDistractors":[{"contextId":"u1_01_leisure_gap_meaning_sentence","answer":"leisure time","wrong":["homework","working hours","uniform"]},{"contextId":"u1_01_leisure_gap_x1","answer":"leisure time","wrong":["homework","school hours","rent"]},{"contextId":"u1_01_leisure_gap_x2","answer":"leisure time","wrong":["income","noise","crime"]}],"spellingErrors":["leisur time","lesiure time","liesure time","leasure time","leisuer time","lesure time"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_leisure' and jsonb_array_length(senses) >= 1;
update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["Our school rule says every student must take part in a team sport.","He chose swimming because there was no space left in the other classes.","The coach decided who would play in defence without asking the players.","She dislikes team games and avoids joining any of them."],"gapDistractors":[{"contextId":"u1_02_preference_gap_meaning_sentence","answer":"preference","wrong":["dislike","complaint","disagreement"]},{"contextId":"u1_02_preference_gap_x1","answer":"preference","wrong":["complaint","penalty","refund"]},{"contextId":"u1_02_preference_gap_x2","answer":"preference","wrong":["complaint","refund","discount"]}],"spellingErrors":["preferance","prefrence","prefference","preferrence","prefernce","preferense"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_preference' and jsonb_array_length(senses) >= 1;
update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["He ran straight into the crowded training area without checking.","His team looked for every chance to take risks in the final.","She tried a new sport every month to see which one she liked.","The coach warned him that the injury could get worse if he kept playing.","He walked straight towards the heavy traffic without looking, and he nearly caused an accident.","Their captain asked everyone to run towards the loudest, most crowded part of the stadium."],"gapDistractors":[{"contextId":"u1_03_avoid_gap_base_noun","answer":"avoid","wrong":["take","seek","welcome"]},{"contextId":"u1_03_avoid_gap_third_ing","answer":"avoids","wrong":["hopes","wants","expects"]},{"contextId":"u1_03_avoid_gap_past_noun","answer":"avoided","wrong":["calculated","reported","measured"]},{"contextId":"u1_03_avoid_gap_perfect_ing","answer":"avoided","wrong":["enjoyed","practised","resumed"]},{"contextId":"u1_03_avoid_gap_plural_ing","answer":"avoid","wrong":["enjoy","prefer","practise"]}],"spellingErrors":["aviod","avoyd","avoide","avoied","avode","avoidd"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_avoid' and jsonb_array_length(senses) >= 1;
