update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["He felt angry that the coach picked another player.","She was happy about the choice she made.","He felt nervous about the choice he had to make.","She told everyone proudly that she had chosen to retire.","She felt delighted about her decision to join a much bigger club.","He was proud of the brave choice he made, and he never looked back at his old team.","She smiled happily when the long journey to the tournament was finally over.","Visitors to the museum admired the old trophies in the glass cabinets."],"gapDistractors":[{"contextId":"u1_13_regret_gap_base_ing","answer":"regret","wrong":["hope","plan","want"]},{"contextId":"u1_13_regret_gap_third_ing","answer":"regrets","wrong":["hopes","plans","wants"]},{"contextId":"u1_13_regret_gap_past_ing","answer":"regretted","wrong":["hoped","planned","wanted"]},{"contextId":"u1_13_regret_gap_perfect_that","answer":"regretted","wrong":["photographed","inspected","repaired"]},{"contextId":"u1_13_regret_gap_past_that","answer":"regretted","wrong":["photographed","inspected","repaired"]}],"spellingErrors":["regrett","regert","regrat","regreat","reggret","rigret"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_regret' and jsonb_array_length(senses) >= 1;
