update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["Her club closed two of its three sports halls.","The number of players stayed exactly the same for years.","The league moved all its matches to a new day.","His new coach changed the team's training routine.","The club closed two of its youth teams because there was not enough money.","The population of the village fell steadily, as young people moved away to study in the city.","The head coach resigned after the team lost six matches in a row.","Heavy traffic delayed the visiting team’s coach on the motorway yesterday."],"gapDistractors":[{"contextId":"u1_47_expansion_gap_meaning_sentence","answer":"expansion","wrong":["reduction","closure","decline"]},{"contextId":"u1_47_expansion_gap_x1","answer":"expansion","wrong":["closure","reduction","decline"]},{"contextId":"u1_47_expansion_gap_x2","answer":"expansion","wrong":["reduction","closure","decline"]}],"spellingErrors":["expantion","expanshion","expension","expanssion","expandsion","expasion"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_expansion' and jsonb_array_length(senses) >= 1;
update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["The academy moved to a new address last year.","Their club's yearly fee is paid in two instalments.","The academy has twenty coaches and four pitches.","Our academy was founded by a former champion.","Her coach changed the team’s training time without telling any of the players.","She won three gold medals in a single afternoon, at her very first national competition.","Tickets for the school concert are available from the main office until the end of the week.","Most spectators brought umbrellas because rain was forecast for the afternoon.","Several students collected their certificates from the main office."],"gapDistractors":[{"contextId":"u1_48_reputation_gap_meaning_sentence","answer":"reputation","wrong":["permission","salary","timetable"]},{"contextId":"u1_48_reputation_gap_x1","answer":"reputation","wrong":["permission","uniform","timetable"]},{"contextId":"u1_48_reputation_gap_x2","answer":"reputation","wrong":["permission","timetable","uniform"]}],"spellingErrors":["repution","reputaton","reputasion","repetation","reputashun","reputtation"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_reputation' and jsonb_array_length(senses) >= 1;
update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["The entry fee was far too high for most families.","The gym membership cost more than most students could ever pay.","Nobody in the club could understand the strange new rule about fees.","The tickets for the final were free for every student.","The cost of entering the competition was far too high for most families.","The referee’s rude and unfair decision annoyed both teams as well as the whole noisy crowd.","The sports hall closes for cleaning every weekend afternoon.","The school fundraiser raised enough money for new equipment, and the headteacher thanked every parent."],"gapDistractors":[{"contextId":"u1_49_reasonable_gap_meaning_sentence","answer":"reasonable","wrong":["excessive","enormous","unaffordable"]},{"contextId":"u1_49_reasonable_gap_x1","answer":"reasonable","wrong":["ridiculous","terrible","huge"]},{"contextId":"u1_49_reasonable_gap_x2","answer":"reasonable","wrong":["silly","foolish","absurd"]}],"spellingErrors":["reasonible","resonable","reasonnable","reasonabal","reasenable","reasonble"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_reasonable' and jsonb_array_length(senses) >= 1;
update public.vocabulary_items set senses=jsonb_set(senses,'{0}',(senses->0) || $sx${"situationDistractors":["The shop sold brand-new trainers in every colour.","The museum showed photographs of last year's final.","Collectors paid a high price for a famous player's signed shirt.","The market sold fresh fruit and vegetables every morning.","Every year the town holds a fashion show to promote clothes from young designers.","The shop sells modern gadgets, brand new phones and the latest computer games for teenagers.","Visitors to the market bought fresh vegetables, cheese and bread from local farmers.","The stadium café offers hot drinks, sandwiches and cakes throughout the afternoon."],"gapDistractors":[{"contextId":"u1_50_antiques_gap_meaning_sentence","answer":"antiques","wrong":["rumours","injuries","deadlines"]},{"contextId":"u1_50_antiques_gap_x1","answer":"antiques","wrong":["rumours","bruises","deadlines"]},{"contextId":"u1_50_antiques_gap_x2","answer":"antiques","wrong":["rumours","injuries","storms"]}],"spellingErrors":["antikes","antiqes","antiqus","anteques","antiquies","antikeys"]}$sx$::jsonb), updated_at=now() where vocabulary_id='vocab_antiques' and jsonb_array_length(senses) >= 1;

commit;

-- Verification (expect: words 50 | with_situation 50 | with_gap_rows 50 | gap_rows 182 | with_spelling 50)
select
  count(*) as words,
  count(*) filter (where senses->0 ? 'situationDistractors') as with_situation,
  count(*) filter (where senses->0 ? 'gapDistractors') as with_gap_rows,
  coalesce(sum(jsonb_array_length(senses->0->'gapDistractors')),0) as gap_rows,
  count(*) filter (where senses->0 ? 'spellingErrors') as with_spelling
from public.vocabulary_items
where vocabulary_id in ('vocab_leisure','vocab_preference','vocab_avoid','vocab_afford','vocab_deny','vocab_permit','vocab_arrange','vocab_urge','vocab_recommend','vocab_demand','vocab_threaten','vocab_resent','vocab_regret','vocab_unfamiliar','vocab_racquet','vocab_opponent','vocab_intense','vocab_tournament','vocab_determined','vocab_discipline','vocab_goal_oriented','vocab_achievement','vocab_elite','vocab_overwhelming','vocab_generation','vocab_challenge','vocab_solution','vocab_pastime','vocab_feat','vocab_regardless','vocab_monetary','vocab_estimated','vocab_struggle','vocab_minimum','vocab_championship','vocab_competitor','vocab_relatively','vocab_patience','vocab_atmosphere','vocab_incredible','vocab_criteria','vocab_historic','vocab_selection','vocab_produce','vocab_craftspeople','vocab_significant','vocab_expansion','vocab_reputation','vocab_reasonable','vocab_antiques') and status='live';
